import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. GEOMETRY & MATERIAL
  // ============================================================================
  const geometry = new THREE.PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    toneMapped: false,
  });

  const plane = new THREE.Mesh(geometry, material);

  // ============================================================================
  // 2. LOAD TEXTURE
  // ============================================================================
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      material.colorNode = texture;
      material.needsUpdate = true;
    });
  }

  // ============================================================================
  // 3. APPLY SCENE POSITION (already set by adapter, but documented here)
  // ============================================================================
  plane.position.set(config.scenePosition?.x ?? 0, config.scenePosition?.y ?? 0, config.scenePosition?.z ?? 0);
  plane.rotation.set(config.scenePosition?.rotationX ?? 0, config.scenePosition?.rotationY ?? 0, config.scenePosition?.rotationZ ?? 0);
  plane.scale.set(config.scenePosition?.scaleX ?? 1, config.scenePosition?.scaleY ?? 1, config.scenePosition?.scaleZ ?? 1);

  // ============================================================================
  // 4. TEXT OVERLAY (headline "Journal 3")
  // ============================================================================
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find((item) => item.role === 'headline') || textItems[0];

  if (headlineItem && headlineItem.text) {
    const textObj = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'center',
    });
    textObj.position.z = 0.01;
    plane.add(textObj);
  }

  // ============================================================================
  // 5. INTERACTION HANDLERS
  // ============================================================================
  const handlers = {};
  let hoverTimeline = null;
  let pressTimeline = null;

  handlers.onPointerEnter = () => {
    // Kill any existing timelines
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();

    // Rise-in animation: y +0.15 -> 0, power3.out, 0.7s
    hoverTimeline = gsap.to(plane.position, {
      y: plane.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  handlers.onPointerLeave = () => {
    if (hoverTimeline) hoverTimeline.kill();

    // Return to original y position
    hoverTimeline = gsap.to(plane.position, {
      y: config.scenePosition?.y ?? 0,
      duration: 0.5,
      ease: 'power2.inOut',
    });
  };

  handlers.onClick = () => {
    // Press-down: scale 0.97, 120ms, back.out
    if (pressTimeline) pressTimeline.kill();

    pressTimeline = gsap.to(plane.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(plane.scale, {
          x: 1,
          y: 1,
          duration: 0.3,
          ease: 'power2.out',
        });
      },
    });

    // Emit navigation event
    ctx.emit('navigate', { to: 'hub-journal' });
  };

  // ============================================================================
  // 6. ATTACH HANDLERS TO USERDATA
  // ============================================================================
  plane.userData.handlers = handlers;

  // ============================================================================
  // 7. CLEANUP
  // ============================================================================
  plane.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    geometry.dispose();
    material.dispose();
  };

  return plane;
}
